        P += 0.25 * ((d / dist[..., None]) * overlap[..., None]).sum(1)
        if i < iterations * 0.75:                       # the last quarter only resolves overlaps
            P -= 0.03 * (P - P.mean(0))
    return {n: (float(x), float(y)) for n, (x, y) in zip(core, P)}

