content.content:
.report__empty { padding: 28px; text-align: center; border: 1px dashed var(--input-border-color); border-radius: 12px; background: var(--surface-background-secondary); display: flex; flex-direction: column; gap: 4px; }
.report__panel { padding-top: 20px; }
.report { display: flex; flex-direction: column; gap: 28px; max-width: 980px; }
.report__bottom { padding: 18px 20px; border-radius: 14px; border: 1px solid var(--border); border-left-width: 5px; background: var(--surface-background-secondary); }
.report__bottom--go { border-left-color: var(--success); background: var(--success-background); }
.report__bottom--maybe { border-left-color: var(--cta); background: var(--cta-soft); }
.report__bottom--low { border-left-color: var(--muted-soft); }
.report__bottom--unknown { border-left-color: var(--warning); background: var(--warning-background); }
.report__kicker { font-size: 12.5px; font-weight: var(--w-clickable); color: var(--text-2); }
.report__answer { margin-top: 4px; font-size: 21px; line-height: 1.4; font-weight: 600; letter-spacing: -0.015em; color: var(--heading); max-width: 62ch; }
.report__move { margin-top: 8px; font-size: var(--fs-small); color: var(--text-2); }
.report__headline { margin-top: 14px; padding-top: 12px; border-top: 1px solid rgba(16, 24, 40, 0.08); }
.report__label { font-size: 12px; font-weight: var(--w-clickable); color: var(--text-2); margin-bottom: 4px; }
.report__h { font-size: 17px; }
.report__hint { margin-top: 2px; font-size: 13px; color: var(--disclaimer); }
.report__briefhead { display: flex; justify-content: space-between; align-items: baseline; gap: 12px; flex-wrap: wrap; margin-bottom: 12px; }
.report__verified { font-size: 12.5px; font-weight: 500; color: var(--success); }
.report__tech > summary { font-size: 13px; }
.report__tech > p { margin-top: 8px; }

.recgroups { margin-top: 12px; display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 12px; }
.recgroup { padding: 14px 16px; border-radius: 12px; border: 1px solid var(--border); border-top-width: 4px; background: #fff; }
.recgroup--go { border-top-color: var(--success); }
.recgroup--maybe { border-top-color: var(--cta); }
.recgroup--low { border-top-color: var(--muted-soft); }
.recgroup--unknown { border-top-color: var(--warning); }
.recgroup--na { border-top-color: var(--border); background: var(--surface-background-secondary); }
.recgroup__head { display: flex; justify-content: space-between; align-items: baseline; }
.recgroup__label { font-weight: var(--w-clickable); color: var(--heading); font-size: 15px; }
.recgroup__n { font-size: 20px; font-weight: 700; color: var(--heading); }
.recgroup__meaning { margin-top: 2px; font-size: 13px; color: var(--text-2); }
.recgroup__places { margin: 10px 0 0; padding: 0; list-style: none; display: flex; flex-direction: column; gap: 4px; font-size: 13.5px; }
.recgroup__score { color: var(--disclaimer); font-size: 12px; }
.recgroup__action { margin-top: 8px; font-size: 12.5px; color: var(--text-2); }
.side__group--go { background: var(--success-background); }
.side__group--maybe { background: var(--cta-soft); }
.side__group--low, .side__group--na { background: var(--surface-background-secondary); }
.side__group--unknown { background: var(--warning-background); }

.plainfacts { margin: 12px 0 0; display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }
.plainfacts > div { padding: 12px 14px; border-radius: 12px; background: var(--surface-background-secondary); }
.plainfacts dt { font-size: 12.5px; font-weight: var(--w-clickable); color: var(--text-2); }
.plainfacts dd { margin: 4px 0 0; font-size: 14px; line-height: 1.5; color: var(--copy-text); }
@media (max-width: 767px) { .plainfacts { grid-template-columns: 1fr; } }

.briefsecs { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }
@media (max-width: 900px) { .briefsecs { grid-template-columns: 1fr; } }
.briefsec { padding: 14px 16px; border-radius: 12px; border: 1px solid var(--border); }
.briefsec--next { grid-column: 1 / -1; background: var(--cta-soft); border-color: var(--cta-border); }
.briefsec__title { font-size: 15px; font-weight: var(--w-clickable); }
.briefsec__hint { font-size: 12px; color: var(--disclaimer); margin-bottom: 8px; }
.briefsec__claims { margin: 0; padding-left: 18px; display: flex; flex-direction: column; gap: 8px; }
.briefsec__claims .claim__text { font-size: 14px; line-height: 1.55; }
.briefsec--next .briefsec__claims { list-style: decimal; }
.report .note .spinner { vertical-align: -2px; margin-right: 6px; }

/* ------------------------------------------------------------------ fit the window */
html, body, #root { height: 100%; }
@media (min-width: 1025px) { html, body { overflow: hidden; } }
.app { height: 100vh; height: 100dvh; display: grid; grid-template-rows: var(--nav-h) minmax(0, 1fr); overflow: hidden; }
.app__main { min-height: 0; overflow: hidden; }
.app__main[hidden] { display: none; }
.nav { position: relative; }
.nav__inner { padding: 0 24px; }
.nav__views { display: flex; gap: 3px; padding: 3px; margin-left: 12px; background: var(--surface-background-secondary); border: 1px solid var(--border); border-radius: var(--radius-pill); }
.nav__view { border: 0; background: none; padding: 5px 14px; border-radius: var(--radius-pill); font-size: 12.5px; font-weight: var(--w-clickable); color: var(--text-2); cursor: pointer; }
.nav__view:hover { color: var(--heading); }
.nav__view[aria-current="page"] { background: #fff; color: var(--cta); box-shadow: var(--shadow-sm); }

.landing { height: 100%; overflow-y: auto; display: flex; flex-direction: column; }
.landing .stage { flex: 1; display: flex; align-items: center; }
.landing .stage__inner { padding-top: 32px; padding-bottom: 32px; width: 100%; }

.ws { height: 100%; max-width: none; padding: 14px 20px; grid-template-rows: minmax(0, 1fr); align-items: stretch; }
.ws__main { position: relative; min-height: 0; gap: 12px; overflow-y: auto; overflow-x: hidden; padding: 2px 4px 2px 2px; margin: -2px -4px -2px -2px; }
.ws__flow { flex: none; }
.ws__report { flex: 1 0 auto; padding: 0 22px 22px; container-type: inline-size; }
.ws__report .report__top { padding-top: 16px; }
.ws__report .tabs { position: sticky; top: -2px; z-index: 3; background: #fff; flex-wrap: wrap; column-gap: 22px; row-gap: 0; overflow: visible; }
.side { position: relative; top: auto; height: 100%; max-height: none; }
.flog__list { max-height: 180px; }
