            <Text>{safe(w.title || w.url || "")}</Text>
            <Text style={s.srcProv}>{safe(`${w.url ?? ""} · retrieved ${(w.retrieved_at ?? "").slice(0, 10)}`)}</Text>
          </View>
        </View>
      ))}
    </View>
  );
}

