cd /Users/chiragnvijay/Desktop/Projects/unite_hack/DataMining-Hack && python3 - <<'EOF'
import json, glob, re
from pathlib import Path
issues = []
for f in sorted(glob.glob('competitor-data/extracted/*.jsonl')):
    for i, l in enumerate(open(f), 1):
        if not l.strip() or l.startswith('//'): continue
        r = json.loads(l)
        ev = (r.get('evidence') or '') ; note = r.get('note') or ''
        if r['table'] == 'sales':
            if str(r['year']) not in ev and str(r['year']) not in note:
                issues.append((Path(f).name, i, 'sales-year', r['model_id'], r['year'], ev[:110]))
        if r['table'] == 'price':
            toks = [t for t in re.split(r"[\s/(),]+", r['variant']) if len(t) >= 2 and not re.fullmatch(r"\d{4}", t)]
            low = ev.lower()
            if toks and not any(t.lower() in low for t in toks):
                issues.append((Path(f).name, i, 'price-variant', r['model_id'], r['variant'], ev[:110]))
for x in issues: print(x)
print(len(issues), "flagged")
EOF

